transforms.code:
# Reference binding: the gateway's real schedules mapped to the component's
# flat BasicScheduleModel mirror, plus two synthetic demo shifts appended
# when no gateway schedule already has their name (a save persists them for
# real, after which the gateway copy wins). refreshTick in the expression
# refetches immediately after each save/delete.
DAYS = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday']
def mapSched(s):
	d = {'name': str(s.name), 'description': str(getattr(s, 'description', '') or '')}
	for k in ['observeHolidays', 'allDays', 'repeatAlternating']:
		d[k] = bool(getattr(s, k, False))
	sa = getattr(s, 'startingAt', None)
	d['startingAt'] = system.date.format(sa, 'yyyy-MM-dd') if sa else ''
	for day in DAYS:
		d[day] = bool(getattr(s, day, False))
		d[day + 'Time'] = str(getattr(s, day + 'Time', '') or '')
	return d
out = []
for s in system.user.getSchedules():
	try:
		out.append(mapSched(s))
	except Exception:
		pass
existing = set(d['name'] for d in out)
day = {'name': 'Demo Day Shift', 'description': 'Synthetic (added by the view binding)', 'observeHolidays': True, 'allDays': False, 'repeatAlternating': False, 'startingAt': ''}
night = {'name': 'Demo Night Shift', 'description': 'Synthetic (added by the view binding)', 'observeHolidays': False, 'allDays': False, 'repeatAlternating': True, 'startingAt': ''}
for d in DAYS:
	weekday = d not in ('saturday', 'sunday')
	day[d] = weekday
	day[d + 'Time'] = '8:00-12:00, 12:30-17:00' if weekday else ''
	night[d] = weekday
	night[d + 'Time'] = '0:00-6:00, 22:00-24:00' if weekday else ''
return out + [s for s in [day, night] if s['name'] not in existing]

config.script:
try:
	system.user.removeSchedule(str(event.name))
	self.view.custom.lastEvent = 'onScheduleDelete removed "' + str(event.name) + '"'
except Exception as e:
	self.view.custom.lastEvent = 'onScheduleDelete FAILED: ' + str(e)
self.view.custom.refreshTick = self.view.custom.refreshTick + 1
